except ZeroDivisionError catches only that specific error. except Exception catches all exceptions except SystemExit, KeyboardInterrupt, and GeneratorExit. Catching specific exceptions is better:

```python
# Too broad - hard to debug
try:
    x = int(user_input)
except Exception:
    print("Error")

# Better - specific
try:
    x = int(user_input)
except ValueError:
    print("Input not a valid integer")
```

Specific exceptions make debugging easier and prevent masking unexpected errors.

The else clause runs only if no exception was raised in the try block:

```python
try:
    result = int(user_input)
except ValueError:
    print("Not a valid integer")
else:
    print(f"Successfully converted to {result}")
```

Use else to keep code that depends on successful execution separate from exception handling. This is cleaner than putting everything in the try block.

What's wrong with this code?

try:
    result = 10 / 0
except:
    pass

The new exception propagates up and overwrites the original exception:

```python
try:
    result = 10 / 0
except ZeroDivisionError:
    x = int("abc")  # New exception here
```

This is usually a bug because you lose the original error info. Avoid doing complex work in except blocks, or wrap it in its own try-except:

```python
try:
    result = 10 / 0
except ZeroDivisionError as e:
    try:
        x = int(user_input)
    except ValueError:
        print(f"Also couldn't parse input: {e}")
```

Inherit from Exception or a more specific exception:

```python
class NetworkError(Exception):
    pass

class TimeoutError(NetworkError):
    pass
```

You can add custom attributes:

```python
class ValidationError(Exception):
    def __init__(self, message, field=None):
        super().__init__(message)
        self.field = field

try:
    validate(age)
except ValidationError as e:
    print(f"Error in {e.field}: {e}")
```

Fix this code that tries to parse integers:

def parse_numbers(items):
    result = []
    for item in items:
        try:
            result.append(int(item))
        except:
            pass
    return result

The bare except: is too broad. Specify the exception:

```python
def parse_numbers(items):
    result = []
    for item in items:
        try:
            result.append(int(item))
        except ValueError:
            pass  # Skip non-numeric items
    return result
```

If you want to log failures:

```python
def parse_numbers(items):
    result = []
    for item in items:
        try:
            result.append(int(item))
        except ValueError:
            print(f"Skipping invalid item: {item}")
    return result
```

Catching exceptions too broadly hides bugs:

```python
# Bug: catches programming errors too
for item in items:
    try:
        value = int(item)
        total += value  # Could fail if total is not defined
    except Exception:
        continue

# Better: only catch expected exceptions
for item in items:
    try:
        value = int(item)
    except ValueError:
        continue
    total += value  # This runs after try-except
```

Keep try blocks focused on the specific operation that might fail.

List comprehensions can't use try-except directly. Options:

1. Use a helper function:
```python
def safe_int(x):
    try:
        return int(x)
    except ValueError:
        return None

result = [safe_int(x) for x in items]
result = [x for x in result if x is not None]  # Filter Nones
```

2. Use filter:
```python
def can_parse(x):
    try:
        int(x)
        return True
    except ValueError:
        return False

result = [int(x) for x in items if can_parse(x)]
```

Catch them separately:

```python
try:
    with open('data.txt') as f:
        data = f.read()
except FileNotFoundError:
    print("File doesn't exist")
except PermissionError:
    print("No permission to read file")
except IOError as e:
    print(f"I/O error: {e}")
```

Order matters—catch specific exceptions first, then general ones. FileNotFoundError and PermissionError are both subclasses of OSError.

Multiple issues: bare except, too broad try block, no detail:

```python
try:
    with open('settings.json') as f:
        config = json.load(f)
except FileNotFoundError:
    print('Settings file not found')
    return
except json.JSONDecodeError:
    print('Settings file is not valid JSON')
    return

if 'port' not in config:
    print('Port not specified in settings')
    return

try:
    port = int(config['port'])
except ValueError:
    print('Port must be a number')
    return

try:
    start_server(port)
except Exception as e:
    logging.exception(f'Failed to start server on port {port}')
```

Now each error is specific and actionable.

Let exceptions propagate or handle them explicitly:

```python
class DatabaseConnection:
    def __init__(self, host, port):
        try:
            self.connection = self._connect(host, port)
        except ConnectionError:
            logging.error(f"Failed to connect to {host}:{port}")
            raise  # Re-raise to prevent object creation

    def _connect(self, host, port):
        # Might raise ConnectionError
        return connect(host, port)

# Caller must handle
try:
    db = DatabaseConnection('localhost', 5432)
except ConnectionError:
    print("Cannot connect to database")
```

Don't silently fail in __init__—let the exception propagate so the caller knows object creation failed.

Create a base exception and inherit specific ones:

```python
class PaymentError(Exception):
    """Base for all payment-related errors"""
    pass

class InsufficientFundsError(PaymentError):
    pass

class PaymentGatewayError(PaymentError):
    pass

class InvalidCardError(PaymentError):
    pass

# Callers can catch at different levels
try:
    process_payment(order)
except InsufficientFundsError:
    print("Not enough money")
except InvalidCardError:
    print("Invalid card")
except PaymentError as e:
    logging.error(f"Payment failed: {e}")
```

This lets callers handle specific errors differently while falling back to generic PaymentError if needed.

What's the problem with this exception handler?

try:
    result = compute(data)
except Exception as e:
    print(e)
    return None

Catching the exception but not raising it:

```python
# WRONG - test passes even though function doesn't raise
def test_invalid_input():
    try:
        int("abc")
    except ValueError:
        pass  # Test passes but function didn't actually raise!

# RIGHT - use pytest.raises
def test_invalid_input():
    with pytest.raises(ValueError):
        int("abc")

# RIGHT - use assertRaises
class TestParsing(unittest.TestCase):
    def test_invalid_input(self):
        with self.assertRaises(ValueError):
            int("abc")
```

Always use pytest.raises or assertRaises to ensure the exception is actually raised.

A fixture is a reusable function that sets up test data or state:

```python
import pytest

@pytest.fixture
def sample_list():
    return [1, 2, 3, 4, 5]

def test_sum(sample_list):
    assert sum(sample_list) == 15

def test_length(sample_list):
    assert len(sample_list) == 5
```

Pytest runs the fixture function and passes its return value to each test. Use fixtures to avoid duplicating setup code.

Scope controls how often a fixture is reused:

```python
import pytest

# function (default) - new for each test
@pytest.fixture
def fresh_list():
    return []

# module - created once per file
@pytest.fixture(scope='module')
def database():
    db = connect_to_test_db()
    yield db
    db.close()

# session - created once for entire test run
@pytest.fixture(scope='session')
def config():
    return load_config('test.json')

class TestDatabase:
    def test_one(self, database):
        # database is the same instance
        pass

    def test_two(self, database):
        # database is the same instance as test_one
        pass
```

Use pytest.mark decorators:

```python
import pytest

@pytest.mark.slow
def test_slow_operation():
    # Very slow test
    heavy_computation()

@pytest.mark.skip(reason="Not implemented yet")
def test_future_feature():
    assert expected_feature()

@pytest.mark.skipif(os.environ.get('CI') != 'true',
                    reason="Only run in CI")
def test_integration():
    test_against_real_service()
```

Run with `pytest -m slow` to run only slow tests, or `pytest -m "not slow"` to skip them.

skip prevents the test from running. xfail runs it but expects failure:

```python
import pytest

# Test doesn't run
@pytest.mark.skip
def test_skipped():
    assert False

# Test runs but failure is expected
@pytest.mark.xfail
def test_known_bug():
    assert some_buggy_function() == expected  # May fail

# Strict xfail - fails if test suddenly passes
@pytest.mark.xfail(strict=True)
def test_marked_xfail_must_fail():
    pass  # If this passes, test fails (regression detected!)
```

xfail is useful for documenting known bugs. strict=True catches when bugs are fixed.

monkeypatch replaces objects during tests:

```python
import pytest

def test_environment_variable(monkeypatch):
    monkeypatch.setenv('DATABASE_URL', 'sqlite:///:memory:')
    assert os.environ['DATABASE_URL'] == 'sqlite:///:memory:'

def test_module_function(monkeypatch):
    def mock_api_call(*args):
        return {'status': 'ok'}

    monkeypatch.setattr('mymodule.api_call', mock_api_call)
    assert mymodule.api_call() == {'status': 'ok'}

def test_class_method(monkeypatch):
    class MockDatabase:
        def query(self, sql):
            return []

    monkeypatch.setattr(app, 'database', MockDatabase())
    assert app.get_users() == []
```

monkeypatch automatically undoes changes after the test.

These run once per test class, not per test:

```python
import unittest

class TestExpensiveResource(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        """Run once before all tests in class"""
        cls.resource = expensive_setup()

    @classmethod
    def tearDownClass(cls):
        """Run once after all tests in class"""
        cls.resource.cleanup()

    def test_one(self):
        result = self.resource.process('data1')
        self.assertEqual(result, 'output1')

    def test_two(self):
        result = self.resource.process('data2')
        self.assertEqual(result, 'output2')
```

Use for expensive one-time setup like starting a test server.

Use assertEqual for lists, dicts, and sets:

```python
import unittest

class TestCollections(unittest.TestCase):
    def test_list_equality(self):
        self.assertEqual([1, 2, 3], [1, 2, 3])

    def test_dict_equality(self):
        self.assertEqual(
            {'name': 'Alice', 'age': 30},
            {'name': 'Alice', 'age': 30}
        )

    def test_set_equality(self):
        self.assertEqual({1, 2, 3}, {3, 2, 1})
```

For custom objects, implement __eq__:

```python
class User:
    def __init__(self, name):
        self.name = name

    def __eq__(self, other):
        return self.name == other.name

self.assertEqual(User('Alice'), User('Alice'))
```

Mock requests library or use responses:

```python
from unittest.mock import patch
import requests

@patch('requests.get')
def test_api_call(mock_get):
    mock_get.return_value.json.return_value = {'id': 1, 'name': 'Alice'}
    result = mymodule.fetch_user(123)
    assert result == {'id': 1, 'name': 'Alice'}

# Or use responses library
import responses

@responses.activate
def test_with_responses():
    responses.add(
        responses.GET,
        'https://api.example.com/user/1',
        json={'id': 1, 'name': 'Alice'},
        status=200
    )
    result = mymodule.fetch_user(1)
    assert result == {'id': 1, 'name': 'Alice'}
```

Inspect variable scopes:

```python
def my_function(x, y):
    z = x + y

    # Show local variables
    print(locals())  # {'x': ..., 'y': ..., 'z': ...}

    # Check specific variable
    if 'z' in locals():
        print(f"z is defined: {locals()['z']}")

# Show global variables
print(globals())  # All module-level variables
print(globals().keys())  # Just the names

# Common debugging patterns
def debug_function(**kwargs):
    for name, value in kwargs.items():
        print(f"{name} = {value!r}")

debug_function(x=5, y=10, name='Alice')

# Inspect object attributes
class User:
    def __init__(self, name):
        self.name = name

    def debug_info(self):
        print(vars(self))  # Show instance attributes

user = User('Alice')
user.debug_info()  # {'name': 'Alice'}
```

The dict is shared across calls:

```python
result1 = register_user('Alice')  # {'name': 'Alice'}
result2 = register_user('Bob')     # {'name': 'Bob', 'name': 'Bob'}

# Fix
def register_user(name, attributes=None):
    if attributes is None:
        attributes = {}
    attributes['name'] = name
    return attributes

result1 = register_user('Alice')  # {'name': 'Alice'}
result2 = register_user('Bob')     # {'name': 'Bob'}
```
